create table categories (id int not null generated by default as identity primary key, name varchar(100) not null unique, parent_id int references categories(id));
create table customers (id bigint not null generated always as identity primary key, email varchar(255) not null unique, full_name varchar(200) not null,
  is_active boolean not null default true, created_at timestamp not null, version int not null default 0, bio clob(1M));
comment on table customers is 'People who buy things';
comment on column customers.email is 'Login e-mail, unique';
create table products (id int not null generated by default as identity primary key, sku char(12) not null unique, title varchar(200) not null,
  price decimal(10,2) not null, category_id int references categories(id), image blob(1M), released_on date);
create table orders (id bigint not null generated by default as identity primary key, customer_id bigint not null references customers(id),
  placed_at timestamp not null, shipped_to_id bigint references customers(id));
create table order_items (order_id bigint not null references orders(id), line_no int not null, product_id int not null references products(id),
  quantity int not null, primary key (order_id, line_no));
create table audit_log (happened_at timestamp not null, action varchar(400) not null);
create view order_summary as select o.id, c.email from orders o join customers c on c.id = o.customer_id;
